<template>
  <div class="commisRecord">
    <title-line :title="title" />
    <div class="commisRecord-content">
      <div class="money">
        <div class="icon" />
        <div class="tips">
          红包剩余金额：<span>{{ remmons }}</span>
        </div></div>
      <div class="recordBox">
        <!-- <div class="thead">
          <span>序号</span>
          <span>用户名</span>
          <span>红包金额</span>
          <span>时间</span>
        </div> -->
        <div class="tbody">
          <van-pull-refresh v-model="refreshing" :loading-text="$t('tzjl.tzjl50')" :pulling-text="$t('tzjl.tzjl51')" :loosing-text="$t('tzjl.tzjl52')" :finished-text="$t('tzjl.tzjl53')" @refresh="onRefresh">
            <van-list
              v-model="loading"
              :finished="finished"
              :loading-text="$t('tzjl.tzjl50')"
              finished-text=""
              @load="onLoad"
            >
              <!-- <div v-for="(item,index) in recordList" :key="index" class="list">
                <span>{{ item.orders }}</span>
                <span>{{ item.uname }}</span>
                <span style="color:#e5b762;">{{ item.mons }}</span>
                <span>{{ item.utime }}</span>
              </div> -->
              <is-empty v-if="recordList.length===0" />
              <div v-for="(ele ,index) in recordList" :key="index" class="list">
                <div class="left">
                  <img class="img" :src="ele.pic" alt="">
                  <div class="kind">
                    <span>{{ ele.uname }} <div class="icon" @click="openUrl('https://t.me/'+ele.ufcode)" /></span>
                    <span>{{ ele.utime }}</span>
                  </div>
                </div>
                <div class="right">
                  <span>{{ ele.mons }}</span>
                  <!-- <span class="green">{{ ele.status }}</span> -->
                </div>
              </div>
            </van-list>
          </van-pull-refresh>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import transIcon4 from '@/assets/portal/trans-icon4.png'
import TitleLine from '../modules/TitleLine'
import { getrecord } from '@/api/user'
export default {
  components: {
    TitleLine
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      title: '红包领取记录',
      recordList: [],
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10,
      remmons: ''
    }
  },
  created() {
  },
  methods: {
    openUrl(url) {
      window.open(url)
    },
    async onLoad() {
      const packid = this.$route.query.packid
      const res = await getrecord({ packid, pages: this.pageNum })
      // res = {
      //   datalist: [
      //     {
      //       utime: '2023-09-26 04:45:48',
      //       uname: '李纲',
      //       ufcode: 'ligang0988',
      //       mons: '3.07',
      //       orders: '1'
      //     }
      //   ],
      //   status: '1',
      //   totalrow: 1,
      //   remmons: '46.93',
      //   msg: '成功',
      //   totalpage: 1
      // }
      this.remmons = res.remmons
      res.datalist.forEach(element => {
        element.pic = transIcon4
      })
      if (this.refreshing) {
        this.recordList = []
        this.refreshing = false
      }
      this.recordList = this.recordList.concat(res.datalist)
      this.loading = false
      this.pageNum++
      if (this.recordList.length >= Number(res.totalrow)) {
        this.finished = true
      }
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    }
  }

}
</script>
