                    background-image: url(~@/assets/portal/record_amount.png);
                    background-position: 0% 0%;
                    background-size: 100% 100%;
                    background-repeat: no-repeat;
                }
                .tips {
                    text-align: left;
                    font-size: 28px;
                    font-weight: 400;
