                        }
                        .kind {
                            display: flex;
                            flex-direction: column;
                            margin-left: 20px;
                            span:first-child {
                                font-size: 26px;
                                font-weight: 400;
                                color: #fff;
                                margin-bottom: 14px;
                                display: flex;
                            }
                            span {
                                font-size: 20px;
                                font-weight: 400;
                                color: #7987a7;
                            }
                            .icon{
                                margin-left: 20px;
                                width: 32px;
                                height: 32px;
                                background: url(~@/assets/portal/customerService/telegramkefu.png) no-repeat 50%;
                                background-size: 100% 100%;
                            }
                        }
                    }
                    .right {
                        display: flex;
                        flex-direction: column;
                        span:first-child {
                            font-size: 26px;
