                        }
                    }
                }
                // .list{
                //     display: flex;
                //     align-items: center;
                //     min-height: 84px;
                //     // border-bottom: 1px solid #283249;
                //     border-bottom-color: #283249;
                //     border-bottom-style: solid;
                //     border-bottom-width: 2px;
                //     span {
                //         display: inline-block;
                //         flex: 1;
                //         font-size: 24px;
                //         text-align: center;
                //         color: #fff;
                //         word-break: break-all;
                //         word-wrap: normal;
                //     }
                // }
            }
        }
    }
}
</style>
